# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["回测里进场价就是 4h 收盘价，0 延迟。","实盘不是：要等官方 K 线落地、算信号、过闸、下市价单、等成交，秒到分钟级。","","这轮量它到底值多少钱。结论：基本不值钱。","","=== 一、数据分工（两边互补）===","","  服务器 1h 60000 根，覆盖 6.8 年 -> 能测「延迟 1 小时」的上界，样本 14999","  本地 1m 但只有 120 天       -> 能测真实的分钟级延迟，样本 720","","1 小时不是真实延迟，但它是上界。连 1 小时都便宜，秒级就不用担心。","","=== 二、结果 ===","","1 分钟延迟（n=720）：","    均值 -0.002%  中位 +0.000%  P10 -0.056%  P90 +0.056%  上涨占比 49.9%","","1 小时延迟（n=14999）：","    均值 +0.010%  中位 +0.003%  P10 -0.553%  P90 +0.580%  上涨占比 50.3%","    147 笔累计：中位 +0.40%  均值 +1.42%","","进场是买入，正的漂移就是买贵了。","1 小时的平均代价 +0.010%，147 笔累计约 1.4% —— 对着 +1175% 的总收益，可以忽略。","","分布也是对称的（上涨占比 50.3%），说明 4h 收盘后没有系统性方向，就是噪声。","","=== 三、这条结论的性质 ===","","这是市场属性，不是策略属性，所以可以长期用，不会因为改参数失效。","它把「回测偏乐观」这类怀疑里的一个具体项划掉了。","剩下的怀疑项：止损滑点（六年从未触发，无从量）、资金费率（spot 不走永续，不适用）、","仓位规模差异（回测全仓，线上 plan_notional 约 70U）。","","=== 四、我自己搞出来的一个错 ===","","第一版量出来均价漂移 +52.707%，最差 +384.703%。","这个数荒谬到一眼就知道不对，但代码不报错、不崩溃，安安静静给了一个能写进报告的假数字。","","原因：bisect_left 找「ts 之后第一根」。本地 1m 只覆盖 2026-07~11，而 4h 从 2020 开始，","于是 2020 年的 4h 收盘点被对到了 2026 年的价格。","","修法是给对齐加容忍度：starts[i] - ts 超过 5 分钟就返回 None，说明这段没数据，跳过。","改完 n 从 13199 掉到 720（正好是 120 天里的 4h 收盘点数）—— 这个数自己就说明对齐对了。","","反向验证：把 TOL 调到无穷、或直接删掉那个 if，两种做法都精确复现 +52.707%。","守卫是真的在挡，不是装饰。","","教训：跨数据集做时间对齐，必须由代码自己检查覆盖范围，不能靠调用方记得。","一个荒谬但沉默的数字，比一个报错的程序危险得多。","","=== 五、顺手删掉一个会骗人的数 ===","","原来输出里有「最差情形：147 笔累计 410333622764%」。","它是把单笔 +12.665% 当成每一笔都发生、还复利 147 次算出来的。","那不是压力测试，那是拿一个没有意义的数吓人。已删掉，并在代码里写明为什么删。","","=== 六、验证 ===","","工具 tools/entrylag.py，两边都能跑。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":96,"theme":"回测「按收盘价成交」的 0 延迟假设值多少钱：基本不值钱","question":"回测假设 0 延迟进场，实盘是秒到分钟级——这个假设值多少钱？","results":{"1m 延迟 (本地 n=720)":{"mean":"-0.002%","median":"0.000%","p10":"-0.056%","p90":"+0.056%","up_ratio":"49.9%"},"1h 延迟 (服务器 n=14999)":{"mean":"+0.010%","median":"+0.003%","p10":"-0.553%","p90":"+0.580%","up_ratio":"50.3%","cum_147_median":"+0.40%","cum_147_mean":"+1.42%"}},"conclusion":"0 延迟假设不是乐观来源；1 小时延迟累计仅 1.4%，对 +1175% 可忽略","property":"市场属性，不是策略属性，长期可用","self_inflicted":"bisect 对齐没检查覆盖范围，2020 年的点被对到 2026 年的价格，得出 +52.707% 均价漂移；荒谬但静默","fix":"加 5 分钟容忍度；n 从 13199 降到 720 自证对齐正确","reverse_validation":"TOL=无穷 与 删掉 if 两种变异都精确复现 +52.707%","removed_misleading":"删掉「最差情形 147 笔累计 410333622764%」——把单笔极值复利 147 次不是压力测试","remaining_optimism_items":["止损滑点（六年未触发，无从量）","资金费率（spot 不适用）","仓位规模差异（回测全仓 vs 线上 70U）"],"account_state":{"spot_usdt":0}}''')
